use crate::ast_slicer::TsAstSlicer;
use anyhow::{Context, Result};
use flowrail_core::graph::{CodebaseGraph, EdgeKind, NodeRole, SemanticEdge, SemanticNode};
use protobuf::Message;
use scip::types::{Index as ScipIndex, SymbolRole};
use std::collections::HashMap;
use std::fs;
use std::path::Path;

pub struct ScipGraphBuilder;

impl ScipGraphBuilder {
    /// Loads a `index.scip` protobuf file generated by `npx @sourcegraph/scip-typescript index`
    /// and builds a complete Cross-File CodebaseGraph.
    pub fn build_from_scip_file(workspace_root: &Path, scip_path: &Path) -> Result<CodebaseGraph> {
        let raw_bytes = fs::read(scip_path)
            .with_context(|| format!("Failed to read SCIP index at {}", scip_path.display()))?;
        let scip_index = ScipIndex::parse_from_bytes(&raw_bytes)
            .context("Failed to decode SCIP protobuf payload")?;

        let mut graph = CodebaseGraph::new();
        let mut file_symbol_owner_ranges: HashMap<String, Vec<(usize, usize, String)>> =
            HashMap::new();

        // Pass 1: Register all Symbol Definitions across all indexed documents
        for doc in &scip_index.documents {
            let rel_path = doc.relative_path.clone();
            let abs_path = workspace_root.join(&rel_path);
            let source_text = fs::read_to_string(&abs_path).unwrap_or_default();
            let ast_symbols =
                TsAstSlicer::analyze_file(&abs_path, &source_text).unwrap_or_default();

            for occ in &doc.occurrences {
                let is_definition = (occ.symbol_roles & (SymbolRole::Definition as i32)) != 0;
                if !is_definition || occ.symbol.starts_with("local ") {
                    continue;
                }

                let start_line = occ.range.first().copied().unwrap_or(0) as usize + 1;
                let matched_ast = ast_symbols
                    .iter()
                    .find(|s| start_line >= s.line_range.0 && start_line <= s.line_range.1);

                let (byte_range, line_range, role, sig_hash, mutates, is_exp) =
                    if let Some(ast_sym) = matched_ast {
                        let inferred_role = Self::classify_role(
                            &rel_path,
                            &occ.symbol,
                            ast_sym.is_contract,
                            ast_sym.mutates_state,
                        );
                        (
                            ast_sym.byte_range,
                            ast_sym.line_range,
                            inferred_role,
                            ast_sym.signature_hash.clone(),
                            ast_sym.mutates_state,
                            ast_sym.is_exported,
                        )
                    } else {
                        let role = Self::classify_role(&rel_path, &occ.symbol, false, false);
                        (
                            (0, 0),
                            (start_line, start_line + 20),
                            role,
                            blake3::hash(occ.symbol.as_bytes()).to_hex().to_string(),
                            false,
                            true,
                        )
                    };

                let node = SemanticNode {
                    symbol_id: occ.symbol.clone(),
                    display_name: Self::short_display_name(&occ.symbol),
                    file_path: rel_path.clone(),
                    byte_range,
                    line_range,
                    role,
                    signature_hash: sig_hash,
                    mutates_domain_state: mutates,
                    is_exported: is_exp,
                };

                graph.upsert_node(node);
                file_symbol_owner_ranges
                    .entry(rel_path.clone())
                    .or_default()
                    .push((line_range.0, line_range.1, occ.symbol.clone()));
            }
        }

        // Pass 2: Connect Cross-File Reference Edges
        for doc in &scip_index.documents {
            let rel_path = &doc.relative_path;
            let owners = match file_symbol_owner_ranges.get(rel_path) {
                Some(list) => list,
                None => continue,
            };

            for occ in &doc.occurrences {
                let is_definition = (occ.symbol_roles & (SymbolRole::Definition as i32)) != 0;
                if is_definition || occ.symbol.starts_with("local ") {
                    continue;
                }

                if !graph.symbol_to_index.contains_key(&occ.symbol) {
                    continue;
                }

                let ref_line = occ.range.first().copied().unwrap_or(0) as usize + 1;
                if let Some((_, _, caller_symbol)) = owners
                    .iter()
                    .find(|(s_line, e_line, _)| ref_line >= *s_line && ref_line <= *e_line)
                    && caller_symbol != &occ.symbol
                {
                    let target_idx = graph.symbol_to_index[&occ.symbol];
                    let target_role = graph.graph[target_idx].role;
                    let edge_kind = if target_role == NodeRole::ContractDefinition {
                        EdgeKind::ReferencesType
                    } else if (occ.symbol_roles & (SymbolRole::WriteAccess as i32)) != 0 {
                        EdgeKind::MutatesState
                    } else {
                        EdgeKind::Calls
                    };

                    graph.add_edge_by_symbols(
                        caller_symbol,
                        &occ.symbol,
                        SemanticEdge {
                            kind: edge_kind,
                            call_site_line: ref_line,
                            is_dynamic_trace: false,
                        },
                    );
                }
            }
        }

        Ok(graph)
    }

    /// Fast local directory scanner: walks all .ts/.tsx files and parses declarations
    /// using oxc_parser to build a valid CodebaseGraph when index.scip is not yet generated.
    pub fn build_from_directory(workspace_root: &Path) -> Result<CodebaseGraph> {
        let mut graph = CodebaseGraph::new();
        let mut all_ts_files = Vec::new();
        Self::collect_ts_files(workspace_root, &mut all_ts_files)?;

        let mut file_symbols_map: HashMap<String, Vec<SemanticNode>> = HashMap::new();

        // Pass 1: Parse all symbols in every TS file
        for file in &all_ts_files {
            let rel_path = file
                .strip_prefix(workspace_root)
                .unwrap_or(file)
                .to_string_lossy()
                .to_string();

            let source_text = fs::read_to_string(file).unwrap_or_default();
            let symbols = TsAstSlicer::analyze_file(file, &source_text).unwrap_or_default();

            let mut node_list = Vec::new();
            for sym in symbols {
                let symbol_id = format!("{}#{}", rel_path, sym.name);
                let role =
                    Self::classify_role(&rel_path, &sym.name, sym.is_contract, sym.mutates_state);

                let node = SemanticNode {
                    symbol_id: symbol_id.clone(),
                    display_name: sym.name.clone(),
                    file_path: rel_path.clone(),
                    byte_range: sym.byte_range,
                    line_range: sym.line_range,
                    role,
                    signature_hash: sym.signature_hash,
                    mutates_domain_state: sym.mutates_state,
                    is_exported: sym.is_exported,
                };
                graph.upsert_node(node.clone());
                node_list.push(node);
            }
            file_symbols_map.insert(rel_path, node_list);
        }

        // Pass 2: Connect cross-file call and type references based on file text
        for (rel_path, nodes) in &file_symbols_map {
            let file_path = workspace_root.join(rel_path);
            let source_text = fs::read_to_string(&file_path).unwrap_or_default();

            for node in nodes {
                let slice = if node.byte_range.1 <= source_text.len()
                    && node.byte_range.0 < node.byte_range.1
                {
                    &source_text[node.byte_range.0..node.byte_range.1]
                } else {
                    &source_text
                };

                for (other_rel, other_nodes) in &file_symbols_map {
                    if other_rel == rel_path {
                        continue;
                    }
                    for target_node in other_nodes {
                        if slice.contains(&target_node.display_name) {
                            let kind = if target_node.role == NodeRole::ContractDefinition {
                                EdgeKind::ReferencesType
                            } else if target_node.mutates_domain_state {
                                EdgeKind::MutatesState
                            } else {
                                EdgeKind::Calls
                            };

                            graph.add_edge_by_symbols(
                                &node.symbol_id,
                                &target_node.symbol_id,
                                SemanticEdge {
                                    kind,
                                    call_site_line: node.line_range.0,
                                    is_dynamic_trace: false,
                                },
                            );
                        }
                    }
                }
            }
        }

        Ok(graph)
    }

    fn collect_ts_files(dir: &Path, files: &mut Vec<std::path::PathBuf>) -> Result<()> {
        if !dir.is_dir() {
            return Ok(());
        }
        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();
            if path.is_dir() {
                let name = path.file_name().unwrap_or_default().to_string_lossy();
                if name != "node_modules" && name != ".git" && name != "dist" && name != "target" {
                    Self::collect_ts_files(&path, files)?;
                }
            } else if let Some(ext) = path.extension()
                && (ext == "ts" || ext == "tsx")
            {
                files.push(path);
            }
        }
        Ok(())
    }

    pub fn classify_role(
        rel_path: &str,
        symbol: &str,
        is_contract: bool,
        mutates_state: bool,
    ) -> NodeRole {
        if is_contract || rel_path.ends_with(".types.ts") || rel_path.ends_with(".dto.ts") {
            NodeRole::ContractDefinition
        } else if rel_path.contains(".controller.")
            || rel_path.contains("/routes/")
            || symbol.contains("Controller")
            || symbol.contains("Handler")
        {
            NodeRole::EntryGate
        } else if rel_path.contains(".repository.") || rel_path.contains(".dao.") || mutates_state {
            NodeRole::DataRepository
        } else if rel_path.contains("/utils/")
            || rel_path.contains("/logger/")
            || rel_path.contains("/helpers/")
        {
            NodeRole::UtilityNoise
        } else {
            NodeRole::BusinessLogic
        }
    }

    pub fn short_display_name(scip_symbol: &str) -> String {
        scip_symbol
            .split('/')
            .next_back()
            .unwrap_or(scip_symbol)
            .to_string()
    }
}
